css:
@font-face { font-family: 'ShunxiBluePixel'; src: url('https://pub-9cfdbb4d14064a6dbe0397ffdff85f4b.r2.dev/font/fusion-pixel-12px-monospaced.woff2') format('woff2'); font-weight: 400; font-style: normal; font-display: swap; }
.phone { --avatar-size: 32px; --message-gap: 8px; font-family: var(--reader-font); color: #344F77; background: linear-gradient(115deg, #EAF3FF, #B5C9DF 36%, #EBF3FC 68%, #BDCEE2); border: 2px solid #A8BCD2; box-shadow: inset 0 0 0 2px #F6FAFF, inset 0 0 0 5px #C9D9EB, 0 9px 24px #57718A24; }
.phone .phone-screen { background: #EDF3FC; border: 1px solid #D3E1F1; }
.phone .phone-status { font-family: var(--reader-font); font-size: 12px; font-weight: 400; color: #344F77; background: #EDF3FC; }
.phone .phone-header { font-family: var(--reader-font); font-size: 18px; font-weight: 400; line-height: 1.6; color: #344F77; background: #EDF3FC; border-bottom: 1px solid #CDDEF0; }
.phone .phone-back { color: #47658B; }
.phone .messages { background: #F4F7FB url('https://pub-9cfdbb4d14064a6dbe0397ffdff85f4b.r2.dev/shunxi/phoneblue.png') center center / cover no-repeat; padding: 10px 12px 20px; scrollbar-width: thin; scrollbar-color: #A8BFDC transparent; }
.phone .messages::-webkit-scrollbar { width: 4px; }
.phone .messages::-webkit-scrollbar-thumb { background: #A8BFDC; border-radius: 4px; }
.phone .message { margin: 18px 0; }
.phone .message-avatar { border-radius: 50%; border: 1px solid #C4D8ED; box-shadow: 0 1px 3px #52749A18; }
.phone .bubble { font-family: var(--reader-font); color: #344F77; font-size: 15px; line-height: 1.7; font-weight: 400; }
.phone .message[data-type=text] .bubble { position: relative; background: #FCFBFA; border: 1px solid #C8DAF0; border-radius: 11px; padding: 9px 11px; box-shadow: 0 1px 2px #6484A608; }
.phone .message.own[data-type=text] .bubble { background: #DCE8F8; border-color: #B6CEEC; }
.phone .message[data-type=text] .bubble::before { content: ''; position: absolute; top: 13px; left: -4px; width: 6px; height: 6px; background: #FCFBFA; border-left: 1px solid #C8DAF0; border-bottom: 1px solid #C8DAF0; transform: rotate(45deg); }
.phone .message.own[data-type=text] .bubble::before { left: auto; right: -4px; background: #DCE8F8; border-left: 0; border-bottom: 0; border-right: 1px solid #B6CEEC; border-top: 1px solid #B6CEEC; }
.phone .message-time { font-family: var(--reader-font); font-size: 11px; line-height: 1.5; color: #718FB5; opacity: 1; margin-top: 4px; }
.phone .message[data-type=voice] .bubble { background: #FCFBFA; border: 1px solid #C8DAF0; border-radius: 11px; }
.phone .message.own[data-type=voice] .bubble { background: #DCE8F8; border-color: #B6CEEC; }
.phone .voice-bar { font-family: inherit; font-size: 14px; color: #5B7FAE; gap: 7px; padding: 10px; }
.phone .voice-hint { font-size: 10px; color: #637FA2; opacity: 1; }
.phone .voice-transcript { font-family: inherit; font-size: 14px; color: #405D83; line-height: 1.7; border-top: 1px dashed #C6D8EC; background: transparent; }
.phone .transfer-card { background: linear-gradient(115deg, #B2CEEE, #CCDDF3); border: 1px solid #A4C3E9; color: #344F77; border-radius: 11px; }
.phone .transfer-main { padding: 13px 11px 10px; gap: 8px; }
.phone .transfer-main strong { font-family: var(--reader-font); font-size: 22px; line-height: 1.5; font-weight: 400; }
.phone .transfer-main span { font-size: 12px; opacity: 1; }
.phone .bubble .transfer-note { font-family: inherit; font-size: 12px; padding: 8px 11px 10px; border-top: 1px dashed #F6FAFF; opacity: 1; }
.phone .transfer-foot { font-family: inherit; font-size: 10px; border-top-color: #EAF2FC; color: #516E95; opacity: 1; }
.phone .image-description, .phone .location-card, .phone .share-card { background: #FCFBFA; border: 1px solid #C8DAF0; border-radius: 11px; color: #405D83; }
.phone .image-description span { opacity: 1; font-size: 13px; }
.phone .message-image, .phone .share-description img { border-radius: 9px; }
.phone .location-caption strong, .phone .share-card strong { font-family: var(--reader-font); font-weight: 400; font-size: 14px; }
.phone .location-caption small { color: #7186A1; opacity: 1; }
.phone .share-description { font-size: 12px; color: #7186A1; opacity: 1; }
.phone .share-thumbnail { background: #E2ECF9; color: #7B9EC9; }
.phone .share-source { color: #6F87A7; border-color: #DAE5F2; opacity: 1; }
.phone .message[data-type=call] .bubble, .phone .message[data-type=video] .bubble { background: #FCFBFA; border: 1px solid #C8DAF0; border-radius: 11px; }
.phone .message.own[data-type=call] .bubble, .phone .message.own[data-type=video] .bubble { background: #DCE8F8; border-color: #B6CEEC; }
.phone .call-record { font-family: var(--reader-font); color: #5579A4; font-size: 13px; }
.phone .phone-footer { background: #EDF3FC; border-top: 1px solid #CDDEF0; color: #7C9FCB; }
.phone .phone-input { background: #FCFBFA; border: 1px solid #C8DAF0; border-radius: 18px; box-shadow: none; }
.phone .phone-home { background: #A5BBD4; opacity: 1; }
